%clear allfprintf(1,'Parlitz Solution\n');global c1 c2 Ro w vis Pv Po Ps Pg c gamma sigma dens f ii P_R t_R tf xo_old told% Given Constants%____________________some mods rgh 2/20/20______________________________________Ro=10.E-06;    	% Equilibrium Radius (m)f=0.12266e6;			% Driving Frequency (Hz)vis=0.001;		% Viscosity of Water @ 20deg C (kg/m-s) = 0.001Pv=2330;			% Vapor Pressure of Water @ 20deg C (Pa)dens=998;		% Density of Water @ 20deg C (kg/m^3)sigma=0.0725;	% Surface Tension (N/m)gamma=1.33;kappa=gamma;     % Effective Polytropic Exponent %Po=1.01575081e5;		% External Ambient Pressure (Pa)Po=1.01e5;		% External Ambient Pressure (Pa)Ps=4.06e5;	% Amplitude of the Driving Acoustic FIeld (Pa)%Ps=0;	% FREE DECAY (Pa)c=1500;			% Speed of Sound in Water @ 20deg C (m/s)c1= Ro;			% Nondimensionalizing Radius Term (1/m)c2= 1e-6;		% Nondimensionalizing Time Term (1/s)NC= 100;			% Number of Cyclesratio=0.44;		% Frequency ratio (f/fo)Ri= 1.5*Ro;			% Initial Bubble Radius (m)xo= [Ri,0];		% Initial Conditionsloopnumber=0;ii=1;%P_R=zeros(10,1);y='y';Y='Y';% Calculated Constants %__________________________________________________________%for Ps =-0.51e5:0.0002e5:-0.508e5;	% start loop% Frequency calculation (Prosperetti, Crum, Commander; JASA V83/N2)% Calculation does not account for surface tension and thermal effects% Minnaert Expression%wo=sqrt(3*kappa*Po/(dens*Ro^2));	% resonance freq of bubble in a liquid%res freq including laPlace pressurewo=sqrt((3*kappa*Po)*((1+2*sigma/(Ro*Po))/(dens*Ro^2))-(2*sigma/(dens*Ro^3)));fo=wo/(2*pi)%f=ratio*fo							% frequency based on the ratio wrt resonance%for i=1:1%for f=27e3:1e2:28e3;%loopnumber=loopnumber+1w= 2*pi*f;							% Driving Frequency (rad/s)%vis=vis+dens*Ro^3*w^2/(4*c)	% effective viscosity der. Devin,Chapman,Plesset,Prosp.frqrat=w/wo%fprintf(1,'f0 = ',fo);%fprintf(1,'frqrat = ',frqrat);ti=0;%xo=xo_old;ti=told;tf=NC/f; %ti= 0.0;								% Initial Time (s)%tf= NC/f;							% Final Time (s)TSPAN= [ti,tf];					% Time Span (s)i=3;rltol=1/(10^(3*i));abtol=rltol*1e-3;% Start Solving Equations% ODE15S Solve stiff differential equations, variable order method. % 'bdf' => backward differentiation formula%__________________________________________________________%options=odeset('bdf', 'on','reltol', rltol,'abstol', abtol);%[tp,yp]=ode15s('parlitz',TSPAN,xo,options);[t,y]=ode15s('parlitz',TSPAN,xo);		Psin=Ps*sin(w*t);		R=y(:,1);		Rless=R;%dummy		Rless([1],:)=[];%removing a row, since 'diff' does by default		Ravg=sum(Rless.*diff(t))/((tf-ti)); %yields a time-weighted avg necessary because of variable time step		Rdot=y(:,2);        %dummy=R^3		Rdotsq=Rdot.*Rdot;		Rless=Rdotsq;		Rless([1],:)=[];		Rdotsqavg=sum(Rless.*diff(t))/((tf-ti));    %do the avg on the square since this is for dissipation		R2dots=diff(Rdot)./diff(t);                 %the crude acceleration		R2dotsavg=sum(R2dots.*diff(t))/((tf-ti));   %this is the avg accel (=0 linear)		tmp=[0];    %here's how to add a row		R2dots=[tmp;R2dots];		qradt=dens*R.*(2*(Rdotsq)+R.*R2dots);%time dependent part		Patravg=qradt/Ravg;%the pressure at Ravg, spherically spreading		Patravgsq=Patravg.*Patravg;%the pressure squared		Pless=Patravgsq;		Pless([1],:)=[];		Psqavg=sum(Pless.*diff(t))/((tf-ti));		Ppeakpos=max(Patravg);  %peak positive at evaluation location		Pavg=sqrt(Psqavg);  %average at evaluation location		Ispta=(Psqavg)/(dens*c);    %temporal avg, so no 2 in denom, W/m^2		POWvis=16*pi*vis*R.*Rdotsq;  %viscous power in watts, total over run		Pless=POWvis;		Pless([1],:)=[];		POWvisavg=sum(Pless.*diff(t))/((tf-ti));    %in Watts		POWviscyc=1e-6*POWvisavg;     %energy in 1 cycle in Joules at 1MHz		POWacoabsdens= 2*18.4*Ispta;     %absorbed acoustic thermal power density, this is 2*alpha*I with LINEAR assumed, W/m^3		POWacoabs=POWacoabsdens*1.3333*pi*(Ravg^3); %total power absorbed within Ravg		Rmax=max(R);		Rmax_Ro=max(R)/Ro;		Ravg_Ro=Ravg/Ro;		%		this FFT works but scaling sometimes a problem[freq,peaks]=mc_fft(max(t)/(2^12),interp1(t,R-Ro,linspace(min(t),max(t),2^12)));figure;plot(freq/fo,peaks);axis([0 max(freq/fo) 0 max(peaks)]);%		this raw FFT is even crappier!!%alt=fft(R-Ro);%figure;%plot (abs(alt));%R vs timefigure;plot(t/1e-6,R/Ro);%axis([0 3 795 811.3]);%the continuous phase portrait%figure%plot(R/Ro, Rdot/Ro)%The pressure in the gas vs time%figure%plot(t/1e-6,P_R)% Display the largest expansion and velocity%max(R)/Ro%max(Rdot)/1e3%s_wave=sin(w*tp);% Plotting commands%__________________________________________________________%plot(tp,1e5*Rp,'r-',tp,s_wave,'b-')%hold on%subplot (2,1,1), plot(tp/c2,Rp);%title('Response of Bubble Collapse');%ylabel('Bubble Radius (R/Ro)');%subplot (2,1,2), plot(tp/c2,s_wave);%ylabel('Bubble Radial Velocity (km/s)');%xlabel('Time (microseconds)');%hold on;%end								% End loop